head.script:
scwin.onpageload = function() {
	var jsonData = [{
		"col1": "a1",
		"col2": "a1"
	}, {
		"col1": "a2",
		"col2": "a2"
	}, {
		"col1": "a3",
		"col2": "a3"
	}, {
		"col1": "a4",
		"col2": "a4"
	}, {
		"col1": "a5",
		"col2": "a5"
	}, {
		"col1": "a6",
		"col2": "a6"
	}];
	dataList1.setJSON(jsonData);
};
scwin.checkLayout = function() {
	var widthAt = parseInt(((j) => j.length ? j : $('#mf_autoComplete1_gridViewItemTable'))($('#autoComplete1_gridViewItemTable')).css("width"));
	var widthBox = parseInt(((j) => j.length ? j : $('#mf_autoComplete1'))($('#autoComplete1')).css("width"));
	return Math.abs(widthAt - widthBox) < 10;
};
scwin.checkLayout2 = function() {
	var widthAt = parseInt(((j) => j.length ? j : $('#mf_sel1_gridViewItemTable'))($('#sel1_gridViewItemTable')).css("width"));
	var widthBox = parseInt(((j) => j.length ? j : $('#mf_sel1'))($('#sel1')).css("width"));
	return Math.abs(widthAt - widthBox) < 10;
};
